/* @autogenerated */
import { LocalRouterService } from './local-router.service';

describe('LocalRouterService', () => {
  it('sends route to bound context', () => {
    const service = new LocalRouterService();
    const bind = { go: jasmine.createSpy('go') };
    (service as any).context = { param: 'view', bind };

    service.go('list');
    expect(bind.go).toHaveBeenCalledWith({ view: 'list' });

    service.go();
    expect(bind.go).toHaveBeenCalledWith({});
  });
});
